mapper.select:
/* SQL_ID: com.hanatour.air.ols.flightPriceSnapshot.ec.qc.FlightPriceSnapshotMapper.findFlightPriceSnapshotList */ SELECT * FROM ( SELECT COUNT(*) OVER() AS TOTAL_COUNT , A.SNAPSHOT_ID , A.RESERVATION_CODE , A.TRIP_TYPE , A.IS_DIRECT_ONLY AS DIRECT_ONLY_YN , TO_CHAR(A.DEP_DATE, 'YYYY-MM-DD') AS DEP_DATE , A.DEP_AIRPORT , A.DEP_AIRLINE_CODE , A.DEP_FLIGHT_NO , TO_CHAR(A.RETURN_DATE, 'YYYY-MM-DD') AS RETURN_DATE , A.RETURN_AIRPORT , A.RETURN_AIRLINE_CODE , A.RETURN_FLIGHT_NO , A.PROMO_CARD_CODE , A.SEAT_CLASS , A.PASSENGER_TYPE , TO_CHAR(A.BASE_FARE, 'FM999999999990.00') AS BASE_FARE , TO_CHAR(A.TAX, 'FM999999999990.00') AS TAX , TO_CHAR(A.Q_CHARGE, 'FM999999999990.00') AS Q_CHARGE , A.CURRENT_RANK , TO_CHAR(A.CAPTURED_AT, 'YYYY-MM-DD HH24:MI:SS') AS CAPTURED_AT FROM AIR01.FLIGHT_PRICE_SNAPSHOT A WHERE A.RESERVATION_CODE = #{reservationCode}
AND A.CAPTURED_AT >= TO_DATE(#{startDt}, 'YYYYMMDD')
/* 종료일자 당일 23:59:59 까지 포함 */ AND A.CAPTURED_AT < TO_DATE(#{endDt}, 'YYYYMMDD') + 1
ORDER BY A.CAPTURED_AT DESC, A.SNAPSHOT_ID DESC ) WHERE ROWNUM <= #{maxRows}
